#!/usr/bin/env bash
# video-subtitle-workflow skill 安装器（自解压，使用 Python 解 zip）
set -euo pipefail
TARGET="${1:-$HOME/.codebuddy/skills}"
DEST="$TARGET/video-subtitle-workflow"
echo "📦 安装 video-subtitle-workflow -> $DEST"
mkdir -p "$DEST"
TMP="$(mktemp /tmp/video-subtitle-workflow.XXXXXX.zip)"
base64 -d <<'__B64__' > "$TMP"

__B64__
python3 - "$TMP" "$DEST" <<'__PY__'
import sys, zipfile, os
tmp, dest = sys.argv[1], sys.argv[2]
parent = os.path.dirname(dest.rstrip("/")) or "."
with zipfile.ZipFile(tmp) as z:
    z.extractall(parent)
os.remove(tmp)
print("   已解压到", dest)
__PY__
echo "✅ 完成。在 CodeBuddy 中调用该 skill 即可使用。"
echo "   测试：python3 $DEST/scripts/check_environment.py --install"
